/**
 * The C# SDK (bit 15): a package emitted from the IR alone (H2): `<PackageId>.csproj`, a root `.editorconfig`,
 * `Client.cs` (the client and its resource classes), `Types.cs` (every component C# declares, then every hoisted
 * declaration, in name order), `JsonContext.cs` (the public source-generated context) and the vendored runtime under
 * `Runtime/`, every `.cs` file in the SDK's own namespace (Fb2) and marked `@generated`, never `<auto-generated`.
 * `Types.cs` ends with `ErrorKey` when the API declares an error key (Fc3). Every body (JSON, form, multipart, text,
 * binary) and every unary answer (JSON, text, bytes) emits; SSE, WebSocket and realtime operations are refused,
 * naming the operation, until phase d (Fb1).
 */
import { type OpenApiDocument, toIR } from "../../ir/build.ts"
import type { IR, IRSchema } from "../../ir/model.ts"
import { type SdkOp, sdkModel } from "../../ir/sdk-model.ts"
import { compareCodeUnits, csTypeName } from "../shared/lang.ts"
import { csharpErrorKeys } from "./errors.ts"
import { jsonContext, runtimeOf, strictConverters, typeInfoNames } from "./json.ts"
import { clientDecls } from "./sdk-client.ts"
import {
	csproj,
	EDITORCONFIG,
	validateClientName,
	validatePackageId,
	validateRootNamespace,
	validateVersion,
} from "./sdk-csproj.ts"
import { docLines } from "./sdk-doc.ts"
import type { CSharpCallPlan } from "./sdk-plan.ts"
import { runtimeFiles } from "./transport.ts"
import { usings } from "./types-names.ts"
import { type CsTypeContext, csTopLevel, csTypeContext, declares } from "./types.ts"

export type CSharpSdkOptions = {
	/** the NuGet package id and assembly name; `HoneySdk` by default */
	readonly packageId?: string
	/** the namespace of every type; the package id by default */
	readonly rootNamespace?: string
	/** the client class; `<last namespace segment>Client` by default */
	readonly clientName?: string
	/** the package version; `0.1.0` by default */
	readonly version?: string
	/** false: each method answers an `SdkResult` instead of throwing an error status; true by default */
	readonly throwOnError?: boolean
}

export type GeneratedCSharpSdk = { readonly files: Readonly<Record<string, string>> }

/* the marker every .cs file opens with; never `<auto-generated`, which the format gate and the analyzers skip (Q4) */
const MARKER = "// @generated by honey. DO NOT EDIT."

/* what this emitter does not generate yet (Fb1, phase d), by what the operation is */
const STREAMS: Readonly<Record<string, string>> = {
	realtime: "is a realtime channel",
	sse: "streams server-sent events",
	ws: "is a WebSocket",
}

/** Throws for a stream operation, which phase d generates, naming it and what it is. */
function refuseLater(op: SdkOp): void {
	const what = op.stream === null ? undefined : STREAMS[op.stream]
	if (what !== undefined) {
		throw new Error(`C# SDK: operation ${JSON.stringify(op.id)} ${what}, which this emitter does not generate yet`)
	}
}

/** The options validated, each default filled in, and the client's and its context's class names. */
function identity(options: CSharpSdkOptions) {
	const packageId = validatePackageId(options.packageId ?? "HoneySdk")
	const rootNamespace = validateRootNamespace(options.rootNamespace ?? packageId)
	const client = validateClientName(
		options.clientName ?? `${csTypeName(rootNamespace.split(".").at(-1) as string)}Client`,
	)
	const version = validateVersion(options.version ?? "0.1.0")
	return { client, context: `${client.replace(/Client$/, "")}JsonContext`, packageId, rootNamespace, version }
}

/** A `.cs` file: the marker, the usings its code needs, the namespace, then the code. */
const csFile = (namespace: string, code: string) =>
	[MARKER, ...usings(code), "", `namespace ${namespace};`, ...(code === "" ? [] : ["", code]), ""].join("\n")

/** Each component C# declares, in code-unit order, its description as its summary: [name, text]. */
function componentDecls(ir: IR, at: CsTypeContext): [string, string][] {
	return Object.keys(ir.schemas)
		.sort(compareCodeUnits)
		.filter((name) => declares(ir.schemas[name] as IRSchema))
		.map((name) => {
			const claimed = at.names.ref(name)
			const text = csTopLevel(claimed, ir.schemas[name] as IRSchema, at)
			return [claimed, [...docLines("summary", ir.schemaDescriptions[name]), text].join("\n")]
		})
}

/** The package's files for `document`, and the call plan of every method in them. */
function emitCSharp(document: Record<string, unknown>, options: CSharpSdkOptions) {
	const id = identity(options)
	const ir = toIR(document as OpenApiDocument, { deriveOperationIds: true })
	const model = sdkModel(ir)
	for (const op of model.ops) refuseLater(op)
	const at = csTypeContext(ir, [id.client, id.context])
	const components = componentDecls(ir, at)
	const errorKey = csharpErrorKeys(model, at)
	const env = {
		at,
		client: id.client,
		context: id.context,
		ops: model.opsById,
		throwOnError: options.throwOnError ?? true,
	}
	const client = clientDecls(ir, env)
	const decls = [...components, ...[...at.decls].sort(([a], [b]) => compareCodeUnits(a, b))]
	const types = [...decls.map(([, text]) => text), ...(errorKey === null ? [] : [errorKey])].join("\n\n")
	const runtime = runtimeOf(at.enums)
	const used = [...client.types, ...at.serialized, ...(/\bJsonElement\b/.test(types) ? ["JsonElement"] : [])]
	const names = typeInfoNames(
		decls.map(([name]) => name).filter((name) => !at.unlisted.has(name)),
		used.map(runtime),
		id.context,
	)
	const spell = { info: (type: string) => `${id.context}.Default.${names.get(runtime(type))}`, runtime }
	const ns = id.rootNamespace
	const files: Record<string, string> = {
		".editorconfig": EDITORCONFIG,
		[`${id.packageId}.csproj`]: csproj(id),
		"Client.cs": csFile(ns, client.text(spell)),
		"JsonContext.cs": csFile(ns, jsonContext(id.context, names, strictConverters(at.collections, runtime))),
		"Types.cs": csFile(ns, types),
		...Object.fromEntries(
			Object.entries(runtimeFiles({ realtime: false, ws: false }, ns)).map(([n, s]) => [`Runtime/${n}`, s]),
		),
	}
	const sorted = Object.fromEntries(Object.entries(files).sort(([a], [b]) => compareCodeUnits(a, b)))
	return { files: sorted, plans: client.plans }
}

/** The package's files for `document`, by path. */
export function generateCSharpSdk(
	document: Record<string, unknown>,
	options: CSharpSdkOptions = {},
): GeneratedCSharpSdk {
	return { files: emitCSharp(document, options).files }
}

/**
 * Each operation's call plan by id, from the very emit `generateCSharpSdk` runs with these options: the names the
 * fixed reflection driver walks (Fb10), never re-derived outside the emitter.
 */
export function csharpCallPlans(
	document: Record<string, unknown>,
	options: CSharpSdkOptions = {},
): Readonly<Record<string, CSharpCallPlan>> {
	return Object.fromEntries(emitCSharp(document, options).plans.map((plan) => [plan.operation, plan]))
}
